#!/usr/bin/env python3
"""Embed firmware/web/device_page.html into firmware/src/web_page.h (gzip not used: keeps it debuggable).
Run after editing the page:  python3 firmware/tools/embed_page.py
The generated header is committed so a plain `pio run` needs no extra step."""
import pathlib

fw = pathlib.Path(__file__).resolve().parent.parent
html = (fw / "web" / "device_page.html").read_text(encoding="utf-8")
assert ')WFGPAGE"' not in html
out = fw / "src" / "web_page.h"
out.write_text(
    "// GENERATED by tools/embed_page.py from web/device_page.html - do not edit by hand.\n"
    "#pragma once\n#include <pgmspace.h>\n"
    f"static const char WFG_PAGE_HTML[] PROGMEM = R\"WFGPAGE({html})WFGPAGE\";\n",
    encoding="utf-8",
)
print(f"wrote {out} ({len(html.encode())} bytes of HTML)")
